def choose_move(observation):
    # Defensive defaults
    cols = observation.get('cols', 0)
    rows = observation.get('rows', 0)
    pos = tuple(observation.get('position', (0, 0)))
    grid = observation.get('grid', {})  # expected to be dict with (x,y)->cell content
    resources = observation.get('resources', {})
    enemies = observation.get('enemies', [])
    allies = observation.get('allies', [])
    mode = observation.get('mode', 'unknown')

    x, y = pos

    # Helper: safe move check within bounds if provided
    def in_bounds(nx, ny):
        if rows and cols:
            return 0 <= nx < cols and 0 <= ny < rows
        return True

    # Helper: check cell content
    def cell(nx, ny):
        return grid.get((nx, ny))

    # Prioritize simple defensive patterns:
    # 1) If there is an adjacent resource, move onto it.
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            if dx == 0 and dy == 0:
                continue
            nx, ny = x + dx, y + dy
            if not in_bounds(nx, ny):
                continue
            if observation.get('mode', mode) in ('resource_collection', 'territory_control', 'pursuit_evasion'):
                if cell(nx, ny) == 'resource':
                    return [dx, dy]

    # 2) If pursuing an evader and adjacent, move towards them
    if mode in ('pursuit_evasion', 'territory_control'):
        targets = enemies if isinstance(enemies, list) else []
        if targets:
            # choose the closest enemy
            best = None
            bestd = None
            for e in targets:
                ex, ey = e.get('position', (0, 0))
                d = abs(ex - x) + abs(ey - y)
                if bestd is None or d < bestd:
                    bestd = d
                    best = (ex, ey)
            if best is not None:
                ex, ey = best
                dx = 0 if ex == x else (1 if ex > x else -1)
                dy = 0 if ey == y else (1 if ey > y else -1)
                if in_bounds(x + dx, y + dy):
                    return [dx, dy]

    # 3) Be grid-stable: avoid walls marked as 'wall' and stay central if possible
    safe_dirs = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            if dx == 0 and dy == 0:
                continue
            nx, ny = x + dx, y + dy
            if not in_bounds(nx, ny):
                continue
            c = cell(nx, ny)
            if c in (None, 'empty', 'resource', 'ally', 'goal'):
                safe_dirs.append((dx, dy))
    if safe_dirs:
        # Prefer straight moves towards center-ish or away from known threats
        # simple heuristic: pick a direction that keeps x,y near center if center exists
        center_x = (cols - 1) / 2 if cols else x
        center_y = (rows - 1) / 2 if rows else y
        def score(dx, dy):
            nx, ny = x + dx, y + dy
            return -abs(nx - center_x) - abs(ny - center_y)
        best = max(safe_dirs, key=lambda d: score(d[0], d[1]))
        return [best[0], best[1]]

    # 4) If nothing else, stay or move randomly among valid small moves
    for dx, dy in ((1,0), (-1,0), (0,1), (0,-1), (0,0)):
        nx, ny = x + dx, y + dy
        if in_bounds(nx, ny):
            if cell(nx, ny) in (None, 'empty', 'resource', 'ally', 'goal'):
                return [dx, dy]

    # Fallback: stay
    return [0, 0]

